    needs_phone = contact.phone != null and contact.phone != "" and not regex.test(contact.phone, "^\\+1[0-9]{10}$")
    new_phone = if needs_phone {
        digits = regex.replace(contact.phone, "[^0-9]", "")
        d = if text.length(digits) == 11 and text.starts_with(digits, "1") {
            return digits
        } else if text.length(digits) == 10 {
            return "1" + digits
        } else {
            return digits
        }
        return "+" + d
    } else {
        return null
    }
    phone_ok = new_phone != null and regex.test(new_phone, "^\\+1[0-9]{10}$")

    needs_company = (contact.company == null or contact.company == "") and contact.email != null and contact.email != ""
    new_company = if needs_company {
        parts = text.split(contact.email, "@")
        domain = parts[1] if list.length(parts) >= 2 else null
        return domain_to_company[domain] if domain != null and domain in domain_to_company else null
    } else {
        return null
    }
    company_ok = new_company != null and new_company != ""

    updated = if phone_ok or company_ok {
        u = update_contact({
            id: contact.id,
            phone: new_phone if phone_ok else null,
            company: new_company if company_ok else null
        })
        return { phone: phone_ok, company: company_ok }
    } else {
        return { phone: false, company: false }
    }
    return updated
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company else 0)
}

sub = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, recorded: sub.recorded }

